member.example:
The following example demonstrates how to handle the  event to log the new value.

<SfInPlaceEditor @bind-Value="@EditorValue">
    <InPlaceEditorEvents TValue="string" ValueChange="@OnValueChange"></InPlaceEditorEvents>
</SfInPlaceEditor>

@code {
    private string EditorValue = "Initial Value";

    private void OnValueChange(ChangeEventArgs<string> args)
    {
        Console.WriteLine($"The new value is: {args.Value}");
    }
}

A simple In-place Editor component with a text input.

<SfInPlaceEditor @bind-Value="EditorValue" Type="InputType.Text" Mode="RenderMode.Inline">
</SfInPlaceEditor>
@code {
   private string EditorValue { get; set; } = "Enter some text";
}

The following example demonstrates how to use the  method to save the editor's value.

<SfInPlaceEditor @ref="Editor" TValue="string" Mode="RenderMode.Inline">
    <EditorComponent>
        <Input type="text" @bind-value="@EditorValue" />
    </EditorComponent>
</SfInPlaceEditor>
<button @onclick="SaveValue">Save</button>
@code {
    private SfInPlaceEditor<string> Editor;
    private string EditorValue = "Initial Value";

    private async Task SaveValue()
    {
        await Editor.SaveAsync();
    }
}
